create function pg_temp.plan()returns jsonb language sql as $$select'{"provider":"openai","model":"synthetic-no-provider"}'::jsonb$$;
create function pg_temp.analysis(n int,parent int default null)returns jsonb language sql as $$select public.prepare_geo_analysis(pg_temp.i(n),pg_temp.i(101),pg_temp.i(201),pg_temp.i(701),pg_temp.i(703),public.knowledge_hash(public.geo_analysis_source(pg_temp.i(201),pg_temp.i(701),pg_temp.i(703))),pg_temp.plan(),case when parent is null then null else pg_temp.i(parent)end)$$;
create function pg_temp.claim(n int)returns jsonb language sql as $$select public.claim_geo_recommendation(pg_temp.plan(),pg_temp.i(n))$$;
create function pg_temp.invoke(n int)returns jsonb language sql as $$select public.start_geo_analysis_invocation(pg_temp.i(n),(select lease_token from public.geo_analysis_records where id=pg_temp.i(n)),jsonb_build_object('modelPlan',pg_temp.plan(),'sourceHash',(select source_hash from public.geo_analysis_records where id=pg_temp.i(n)),'parameters','{"synthetic":true}'::jsonb,'context','{"findings":[],"geo_signals":[]}'::jsonb,'coverage','{"synthetic":true}'::jsonb))$$;
create function pg_temp.receipt()returns jsonb language sql as $$select'{"response":{"id":"synthetic-response","usage":{"input_tokens":3}},"text":"Actual synthetic raw provider text, retained before parsing.","error":null}'::jsonb$$;
create function pg_temp.preview()returns jsonb language sql as $$select jsonb_build_object('recommendations',jsonb_build_array(jsonb_build_object('type','technical_fix','priority','high','owner','web_developer','title','Review captured title','narrative','Review the exact captured title against the retained finding before requesting a website change.','grounding',jsonb_build_object('finding_ids',jsonb_build_array(pg_temp.i(401)),'query_evidence','[]'::jsonb),'proposed_changes','[]'::jsonb)),'coverage','{"synthetic":true}'::jsonb)$$;
create function pg_temp.decide_analysis(n int,analysis int,op text,actor int default 101)returns jsonb language sql as $$select public.decide_geo_analysis(pg_temp.i(n),pg_temp.i(actor),pg_temp.i(201),pg_temp.i(analysis),op,(select preview_hash from public.geo_analysis_records where id=pg_temp.i(analysis)),'Reviewed exact retained synthetic evidence')$$;
