select pg_temp.check_it(public.claim_geo_recommendation(pg_temp.plan())is null,'background skips synthetic analysis');
select pg_temp.check_it(pg_temp.claim(901)->>'state'='running','targeted synthetic claim allowed');
select pg_temp.check_it(pg_temp.claim(901)is null,'live lease cannot be shared');
select pg_temp.check_it(pg_temp.invoke(901)->>'state'='claimed','provider invoked once');
select pg_temp.check_it(pg_temp.invoke(901)->>'state'='already_started','same intent never silently repeats provider');
select pg_temp.check_it(public.retain_geo_analysis_receipt(pg_temp.i(901),pg_temp.i(999),pg_temp.receipt())->>'state'='lease_lost','unknown token cannot forge response');
select pg_temp.check_it(public.retain_geo_analysis_receipt(pg_temp.i(901),(select lease_token from public.geo_analysis_records where id=pg_temp.i(901)),pg_temp.receipt())->>'state'='retained','raw response retained before parsing');
select pg_temp.check_it(public.retain_geo_analysis_receipt(pg_temp.i(901),(select lease_token from public.geo_analysis_records where id=pg_temp.i(901)),pg_temp.receipt())->>'state'='retained','retention retry is idempotent');
select pg_temp.check_it(public.retain_geo_analysis_receipt(pg_temp.i(901),(select lease_token from public.geo_analysis_records where id=pg_temp.i(901)),pg_temp.receipt()||'{"text":"changed"}')->>'state'='request_conflict','actual receipt cannot be replaced');
