create function pg_temp.fail_analysis_action()returns trigger language plpgsql as $$begin if new.action='audit.analysis.applied'then raise exception 'Synthetic atomic history failure';end if;return new;end$$;
create trigger fixture_analysis_action_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_analysis_action();
select pg_temp.throws('select pg_temp.decide_analysis(911,901,''apply'')','history failure rolls back recommendation replacement');
select pg_temp.check_it((select count(*)=0 from public.geo_recommendations where generation_id=pg_temp.i(901)),'failed history leaves no half-applied generation');
drop trigger fixture_analysis_action_failure on public.shared_action_events;
