select pg_temp.check_it((select state='held'and error_code='provider_outcome_unknown'from public.geo_analysis_records where id=pg_temp.i(903)),'uncertain outcome is explicit');
select pg_temp.check_it(public.retain_geo_analysis_receipt(pg_temp.i(903),(select(invocation->>'token')::uuid from public.geo_analysis_records where id=pg_temp.i(903)),pg_temp.receipt())->>'state'='retained','late uncertain reply retained');
select pg_temp.check_it(pg_temp.decide_analysis(913,903,'resume')->>'status'='queued','operator can request saved response recovery');
